mapper.select:
select *
from t_client_location

    trusted_binding = 1
    and report_time  >=  #{startTime}
    and report_time  <=  #{endTime}


        and session_id = #{sessionId}


        and user_id = #{userId}


        and node_id = #{nodeId}


        and mac = #{mac}


order by report_time asc, id asc
limit #{limit}
